# ── Dialog centering ────────────────────────────────────────────────────────
class _DialogCenterFilter(QObject):
    """
    App-wide event filter that centers every QDialog (including QMessageBox,
    QFileDialog, QColorDialog, QProgressDialog, etc. -- all QDialog subclasses)
    on its screen instead of leaving placement to the window manager.

    Qt sends a hidden Move event after a dialog has its final layout size but
    before its first Show event. Centering there avoids both random placement
    and a visible post-show jump.
    """

    def eventFilter(self, obj, event):
        if not isinstance(obj, QDialog):
            return False

        centering = bool(obj.property("_centering_in_progress"))
        if (event.type() in (QEvent.Move, QEvent.Resize) and
                not obj.isVisible() and
                not centering):
            self.center(obj)
        elif event.type() == QEvent.Show and not centering:
            # Fallback for a platform/dialog implementation that does not
            # deliver the hidden Move event.
            self.center(obj)
        return False

    @staticmethod
    def center(dialog):
        """Size and position a dialog before its first visible frame."""
        try:
            # Guard only the recursive Move/Resize events generated by this
            # method. A later layout resize must be allowed to recenter again.
            dialog.setProperty("_centering_in_progress", True)
            dialog.ensurePolished()
            dialog.adjustSize()
            parent = dialog.parentWidget()
            screen = (
                dialog.screen()
                or (parent.screen() if parent is not None else None)
                or QApplication.primaryScreen()
            )
            if screen is None:
                return
            frame = dialog.frameGeometry()
            frame.moveCenter(screen.availableGeometry().center())
            dialog.move(frame.topLeft())
        except RuntimeError:
            # The dialog may have been deleted while an event is in flight.
            pass
        finally:
            try:
                dialog.setProperty("_centering_in_progress", False)
            except RuntimeError:
                pass


